(()=>{const $=s=>document.querySelector(s);const loading=$('#loading'),app=$('#app'),progress=$('#progress'),bundleId=$('#bundleId'),bundleName=$('#bundleName'),counts=$('#counts'),grid=$('#textureGrid'),noPreview=$('#noPreview'),prev=$('#prevBtn'),next=$('#nextBtn'),dlg=$('#imageDialog'),dlgImg=$('#dialogImage'),dlgTitle=$('#dialogTitle'),dlgClose=$('#dialogClose');let items=[],idx=0;function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function chip(k,v){return v?`<span class="count">${k} ${v}</span>`:''}function bottom(){requestAnimationFrame(()=>window.scrollTo({top:document.documentElement.scrollHeight,left:0,behavior:'auto'}));setTimeout(()=>window.scrollTo({top:document.documentElement.scrollHeight,left:0,behavior:'auto'}),120)}function render(){if(!items.length)return;const b=items[idx],c=b.typeCounts||{};progress.textContent=`${idx+1} / ${items.length}`;bundleId.textContent=b.bundleId;bundleName.textContent=b.name||'(sans nom)';counts.innerHTML=[chip('Texture2D',c.Texture2D),chip('Material',c.Material),chip('Mesh',c.Mesh),chip('Renderer',c.MeshRenderer),chip('GO',c.GameObject),chip('Objets',b.objectCount)].join('');grid.innerHTML='';for(const t of b.textures||[]){const card=document.createElement('div');card.className='texture';card.innerHTML=`<button type="button"><img loading="lazy" alt="${esc(t.name)}" src="/lab/bundle-shortlist-review-data/${t.file}"><div class="texture-info"><strong>${esc(t.name||'(sans nom)')}</strong><span>${t.width}×${t.height} · ${esc(t.format||'')}</span></div></button>`;card.querySelector('button').addEventListener('click',()=>{dlgTitle.textContent=`${t.name} — ${t.width}×${t.height}`;dlgImg.src=`/lab/bundle-shortlist-review-data/${t.file}`;typeof dlg.showModal==='function'?dlg.showModal():dlg.setAttribute('open','')});grid.appendChild(card)}noPreview.classList.toggle('hidden',(b.textures||[]).length>0);prev.disabled=idx===0;next.disabled=idx===items.length-1;bottom()}function step(n){idx=Math.max(0,Math.min(items.length-1,idx+n));render()}prev.addEventListener('click',()=>step(-1));next.addEventListener('click',()=>step(1));dlgClose.addEventListener('click',()=>typeof dlg.close==='function'?dlg.close():dlg.removeAttribute('open'));let touchX=null;$('#bundleCard').addEventListener('touchstart',e=>{touchX=e.changedTouches[0]?.clientX??null},{passive:true});$('#bundleCard').addEventListener('touchend',e=>{if(touchX==null)return;const x=e.changedTouches[0]?.clientX??touchX,d=x-touchX;touchX=null;if(Math.abs(d)>70)step(d<0?1:-1)},{passive:true});fetch('/lab/bundle-shortlist-review-data/manifest.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}).then(m=>{items=m.bundles||[];loading.classList.add('hidden');app.classList.remove('hidden');render()}).catch(e=>{loading.textContent=`Données absentes : ${e.message}. Lance le script shortlist Termux.`})})();